<?php
namespace App\Services;
use Illuminate\Http\Request;use Illuminate\Support\Facades\{DB,Hash,Mail,RateLimiter,Validator,Log};use Illuminate\Support\Str;use Illuminate\Validation\ValidationException;
class CcsCustomerEmailOtp{
public function ready():bool{$m=config('ccs_customer_email.mailer','smtp');return (bool)config('ccs_customer_email.enabled',false)&&config('mail.mailers.'.$m.'.transport')==='smtp'&&trim((string)config('mail.mailers.'.$m.'.host'))!==''&&trim((string)config('mail.from.address'))!=='';}
private function digest(string $value):string{return hash_hmac('sha256',$value,(string)config('app.key'));}
private function binding(Request $r):string{return $this->digest('session:'.$r->session()->token());}
public function issue(Request $r):array{abort_unless($this->ready(),503,'Email sign-in is not enabled. Please use your workshop login or contact CCS.');$d=Validator::make($r->all(),['email'=>'required|string|email:rfc|max:254'])->validate();$email=mb_strtolower(trim($d['email']));$key=$this->digest('email:'.$email);$ip=$this->digest('ip:'.(string)$r->ip());
foreach([['otp:cooldown:'.$key,1,60],['otp:hour:'.$key,5,3600],['otp:ip:'.$ip,20,900]] as [$limit,$max,$seconds]){if(RateLimiter::tooManyAttempts($limit,$max))throw ValidationException::withMessages(['email'=>'Please wait before requesting another code.']);}foreach([['otp:cooldown:'.$key,60],['otp:hour:'.$key,3600],['otp:ip:'.$ip,900]] as [$limit,$seconds])RateLimiter::hit($limit,$seconds);
$customers=DB::table('customers')->whereNull('deleted_at')->whereRaw('LOWER(TRIM(email)) = ?',[$email])->limit(2)->get();$customer=$customers->count()===1?$customers->first():null;if($customer&&($customer->is_system_walkin??false))$customer=null;$account=$customer?DB::table('customer_portal_accounts')->where('customer_id',$customer->id)->first():null;if($account&&!$account->active)$customer=null;
$id=(string)Str::uuid();$code=str_pad((string)random_int(0,999999),6,'0',STR_PAD_LEFT);DB::table('ccs_customer_email_otps')->insert(['id'=>$id,'customer_id'=>$customer?->id,'account_version'=>$account?->access_version??0,'email_hash'=>$key,'session_hash'=>$this->binding($r),'code_hash'=>$this->digest($id.':'.$code),'attempts'=>0,'expires_at'=>now()->addMinutes(10),'created_at'=>now(),'updated_at'=>now()]);
if($customer){try{Mail::mailer(config('ccs_customer_email.mailer','smtp'))->raw("Your CCS Solutions sign-in code is: $code\n\nIt expires in 10 minutes and works once. Do not share it. If you did not request it, ignore this email.",function($m)use($email){$m->to($email)->subject('CCS Solutions — your sign-in code');});}catch(\Throwable $e){DB::table('ccs_customer_email_otps')->where('id',$id)->update(['customer_id'=>null,'consumed_at'=>now()]);Log::warning('Customer OTP email delivery failed',['exception'=>get_class($e)]);}}
// Same response for missing, shared, revoked and eligible emails; never return the code.
$r->session()->put('ccs_email_challenge',$id);$r->session()->put('ccs_email_address',$email);return ['challenge'=>$id,'message'=>'If this email is registered for an eligible CCS customer, a code has been sent. Check spam too.'];}
public function verify(Request $r):int{$r->validate(['code'=>['required','string','regex:/^[0-9]{6}$/D']]);$id=(string)$r->session()->get('ccs_email_challenge','');$binding=$this->binding($r);$result=DB::transaction(function()use($r,$id,$binding){$n=DB::table('ccs_customer_email_otps')->where('id',$id)->where('session_hash',$binding)->whereNull('consumed_at')->where('expires_at','>',now())->where('attempts','<',5)->increment('attempts',1,['updated_at'=>now()]);if($n!==1)return null;$row=DB::table('ccs_customer_email_otps')->where('id',$id)->first();$match=hash_equals($row->code_hash,$this->digest($id.':'.$r->input('code')));if(!$match||!$row->customer_id){if($row->attempts>=5)DB::table('ccs_customer_email_otps')->where('id',$id)->update(['consumed_at'=>now()]);return null;}$c=DB::table('customers')->where('id',$row->customer_id)->whereNull('deleted_at')->first();$a=DB::table('customer_portal_accounts')->where('customer_id',$row->customer_id)->first();if(!$c||!hash_equals($row->email_hash,$this->digest('email:'.mb_strtolower(trim((string)$c->email))))||($a&&(!$a->active||(int)$a->access_version!==(int)$row->account_version))||(!$a&&(int)$row->account_version!==0)){DB::table('ccs_customer_email_otps')->where('id',$id)->update(['consumed_at'=>now()]);return null;}if(!$a){$aid=DB::table('customer_portal_accounts')->insertGetId(['customer_id'=>$c->id,'username'=>'otp-'.Str::uuid(),'password'=>Hash::make(Str::random(64)),'active'=>true,'access_version'=>1,'created_at'=>now(),'updated_at'=>now()]);}else $aid=$a->id;DB::table('ccs_customer_email_otps')->where('id',$id)->update(['consumed_at'=>now()]);DB::table('audit_logs')->insert(['user_id'=>null,'action'=>'customer_email_otp_login','entity_type'=>'customer','entity_id'=>$c->id,'metadata'=>json_encode(['account_id'=>$aid]),'created_at'=>now(),'updated_at'=>now()]);return (int)$aid;},3);
if(!$result)throw ValidationException::withMessages(['code'=>'The code is invalid, expired or already used. Request a new code if needed.']);return $result;}
}
